{
  "name": "BioShake微孔板恒温振荡器",
  "name_en": "BioShake microplate thermoshaker",
  "manufacturer": "QInstruments",
  "description": "这是一种用于微孔板样品处理的实验室恒温振荡设备，可对板内液体进行振荡混匀并提供温度控制，常用于孵育、酶反应和样品制备等流程。",
  "description_en": "This is a laboratory thermoshaker for processing microplate samples. It provides shaking for liquid mixing and temperature control, and is commonly used for incubation, enzymatic reactions, and sample preparation workflows.",
  "tag_hints": [
    "microplate thermoshaker",
    "sample mixing",
    "temperature control",
    "incubation",
    "microplate handling",
    "lab automation"
  ],
  "actions": [
    {
      "action_name": "auto-home_shaker",
      "description": "使振荡机构回到初始位置。",
      "description_en": "Return the shaker mechanism to its home position."
    },
    {
      "action_name": "auto-lock",
      "description": "锁定样品托架或夹持机构。",
      "description_en": "Lock the sample holder or clamping mechanism."
    },
    {
      "action_name": "auto-set_shake",
      "description": "按设定转速和时长进行振荡混匀。",
      "description_en": "Shake at the specified speed and for the specified duration."
    },
    {
      "action_name": "auto-temp_off",
      "description": "关闭温度控制功能。",
      "description_en": "Turn off temperature control."
    },
    {
      "action_name": "auto-temp_on",
      "description": "开启温度控制并设置目标温度。",
      "description_en": "Turn on temperature control and set the target temperature."
    },
    {
      "action_name": "auto-unlock",
      "description": "解锁样品托架或夹持机构。",
      "description_en": "Unlock the sample holder or clamping mechanism."
    },
    {
      "action_name": "auto-get_info",
      "description": "获取设备信息。",
      "description_en": "Get device information."
    }
  ]
}

